export const notificationsHtml = "<good-main-view title=\"Notifications\" description=\"Try alerts, timed toasts, acknowledgement, and the notification panel.\">\n  <good-section>\n    <good-breadcrumbs [items]=\"breadcrumbs\" />\n    <good-group title=\"Inline alerts\" appearance=\"plain\">\n      <good-alert tone=\"info\" title=\"Always in context\" message=\"An inline alert remains in the page until your application removes it.\" />\n      <good-alert tone=\"warning\" appearance=\"mono\" title=\"Quiet visual style\"\n        message=\"Mono keeps the message neutral and uses color only on the icon.\" />\n      <good-alert tone=\"destructive\" appearance=\"light\" title=\"Dismissible\"\n        message=\"Close this example with its accessible button.\" [dismissible]=\"true\" />\n    </good-group>\n    <good-group title=\"Send a notification\" appearance=\"plain\">\n      <good-action-group orientation=\"responsive\">\n        <good-button (click)=\"show('toast')\">Toast at top right</good-button>\n        <good-button variant=\"secondary\" (click)=\"show('top')\">Slide from top</good-button>\n        <good-button variant=\"outline\" (click)=\"show('inbox')\">Inbox only</good-button>\n      </good-action-group>\n      <good-action-group orientation=\"responsive\">\n        <good-button variant=\"secondary\" (click)=\"requireAcknowledgement()\">Wait for acknowledgement</good-button>\n        <good-button variant=\"outline\" (click)=\"showActions()\">Toast with actions</good-button>\n        <good-button variant=\"ghost\" (click)=\"showTemporary()\">Temporary toast</good-button>\n      </good-action-group>\n      <good-alert tone=\"neutral\" appearance=\"light\" title=\"Notification panel\"\n        message=\"Open the bell in the topbar to review saved messages. Dismiss, mark as read, or acknowledge them there.\" />\n      <p role=\"status\">{{ lastAction() }}</p>\n    </good-group>\n    <good-group title=\"Use this example\" appearance=\"plain\">\n      <good-code-block [code]=\"htmlSource\" language=\"html\" title=\"notifications-page.html\"\n        [collapsible]=\"true\" [collapsedLines]=\"20\" />\n      <good-code-block [code]=\"typescriptSource\" language=\"typescript\" title=\"notifications-page.ts\"\n        [collapsible]=\"true\" [collapsedLines]=\"20\" />\n    </good-group>\n  </good-section>\n</good-main-view>\n";
export const notificationsTs = "import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';\nimport {\n  GoodActionGroupComponent, GoodAlertComponent, GoodBreadcrumbsComponent, GoodButtonComponent,\n  GoodCodeBlockComponent, GoodGroupComponent, GoodMainViewComponent, GoodNotificationCenter,\n  GoodNotificationDelivery, GoodSectionComponent,\n  type GoodBreadcrumbItem,\n} from '@goodui/angular';\nimport { notificationsHtml, notificationsTs } from './source-code.generated';\n\n@Component({\n  selector: 'example-notifications-page',\n  standalone: true,\n  imports: [GoodMainViewComponent, GoodSectionComponent, GoodBreadcrumbsComponent, GoodGroupComponent,\n    GoodActionGroupComponent, GoodButtonComponent, GoodAlertComponent, GoodCodeBlockComponent],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  templateUrl: './notifications-page.html',\n})\nexport class NotificationsPageComponent {\n  readonly center = inject(GoodNotificationCenter);\n  readonly breadcrumbs: readonly GoodBreadcrumbItem[] = [\n    { label: 'Home', route: '/dashboard' }, { label: 'Examples' }, { label: 'Notifications' },\n  ];\n  readonly lastAction = signal('No action selected yet.');\n  readonly htmlSource = notificationsHtml;\n  readonly typescriptSource = notificationsTs;\n\n  show(delivery: GoodNotificationDelivery): void {\n    this.center.publish({\n      title: delivery === 'inbox' ? 'Inbox-only notice' : 'Your changes were saved',\n      message: delivery === 'inbox' ? 'Open the bell to find this message.' : 'This message also stays in the notification panel.',\n      tone: delivery === 'inbox' ? 'brand' : 'success',\n      delivery,\n    });\n  }\n\n  requireAcknowledgement(): void {\n    this.center.publish({\n      title: 'Review required', message: 'This notification stays until you acknowledge it.',\n      tone: 'warning', appearance: 'light', requireAcknowledgement: true, delivery: 'top',\n    });\n  }\n\n  showActions(): void {\n    this.center.publish({\n      title: 'New feature available', message: 'Try the Alert component and its reusable actions.',\n      tone: 'info', appearance: 'outline', delivery: 'toast', duration: 10000,\n      actions: [\n        { label: 'View alerts', route: '/components/alerts' },\n        { label: 'Remind me later', run: () => this.lastAction.set('Remind me later selected.') },\n      ],\n    });\n  }\n\n  showTemporary(): void {\n    this.center.publish({\n      title: 'Temporary toast', message: 'This toast disappears after three seconds and is not stored.',\n      tone: 'neutral', duration: 3000, persist: false,\n    });\n  }\n}\n";
